#!/bin/bash
set -euo pipefail
source /usr/local/lib/ts-up.sh

: "${NODE_NAME:?}" "${TAILNET:?}" "${TAILSCALE_AUTHKEY:?}" "${CLUSTER_SIZE:?}" \
  "${ES_NODE_NAMES:?}" "${ES_HEAP:?}" "${ADMIN_PASSWORD:?}" "${KIBANA_SYSTEM_PASSWORD:?}"

ES_HOME=/opt/elasticsearch
CONF="${ES_HOME}/config"
CERTS="${CONF}/certs"
FQDN="${NODE_NAME}.${TAILNET}"
IP="$(hostname -I | tr ' ' '\n' | grep -m1 -E '^[0-9]+(\.[0-9]+){3}$')"

ts_up "$FQDN" "$CERTS" elasticsearch

# Transport layer uses the private CA generated by the CLI. Let's Encrypt
# certs no longer carry the clientAuth EKU, so they can't do transport mTLS.
install -o elasticsearch -g elasticsearch -m 0644 /transport-certs/ca.crt        "${CERTS}/transport-ca.crt"
install -o elasticsearch -g elasticsearch -m 0644 /transport-certs/transport.crt "${CERTS}/transport.crt"
install -o elasticsearch -g elasticsearch -m 0600 /transport-certs/transport.key "${CERTS}/transport.key"

# Multi-node clusters run in production mode and enforce bootstrap checks.
sysctl -w vm.max_map_count=262144 >/dev/null || echo "WARN: could not raise vm.max_map_count" >&2
ulimit -n 65535 || echo "WARN: could not raise the open file limit" >&2

if [ "$CLUSTER_SIZE" -eq 1 ]; then
  DISCOVERY="discovery.type: single-node"
else
  DISCOVERY="discovery.seed_hosts: [${SEED_HOSTS:-}]
cluster.initial_master_nodes: [${ES_NODE_NAMES}]"
fi

cat > "${CONF}/elasticsearch.yml" <<YML
cluster.name: tailscale-cluster
node.name: ${NODE_NAME}
network.host: 0.0.0.0
network.publish_host: ${IP}
${DISCOVERY}

xpack.security.enabled: true
xpack.security.http.ssl.enabled: true
xpack.security.http.ssl.certificate: certs/http.crt
xpack.security.http.ssl.key: certs/http.key
xpack.security.transport.ssl.enabled: true
xpack.security.transport.ssl.verification_mode: certificate
xpack.security.transport.ssl.certificate: certs/transport.crt
xpack.security.transport.ssl.key: certs/transport.key
xpack.security.transport.ssl.certificate_authorities: [certs/transport-ca.crt]
YML

mkdir -p "${CONF}/jvm.options.d"
printf -- '-Xms%s\n-Xmx%s\n' "$ES_HEAP" "$ES_HEAP" > "${CONF}/jvm.options.d/heap.options"
chown -R elasticsearch:elasticsearch "$CONF"

# File realm users. kibana_system is a reserved name, so Kibana gets its own
# user holding the kibana_system role.
users() { runuser -u elasticsearch -- "${ES_HOME}/bin/elasticsearch-users" "$@"; }
for u in admin kibana_svc; do users userdel "$u" >/dev/null 2>&1 || true; done
users useradd admin      -p "$ADMIN_PASSWORD"         -r superuser
users useradd kibana_svc -p "$KIBANA_SYSTEM_PASSWORD" -r kibana_system

unset TAILSCALE_AUTHKEY ADMIN_PASSWORD KIBANA_SYSTEM_PASSWORD
# runuser -u execs directly instead of going through the account's nologin shell.
exec runuser -u elasticsearch -- "${ES_HOME}/bin/elasticsearch"
